    <pre className="code code-block" tabIndex={0} role="group" aria-label="dockerfile コード例"><div className="code-line">{""}<span className="hljs-comment">{"# 最小権限で動かすコンテナの例"}</span>{""}</div><div className="code-line">{""}<span className="hljs-keyword">{"FROM"}</span>{" public.ecr.aws/docker/library/python:"}<span className="hljs-number">{"3.12"}</span>{"-slim"}</div><div className="code-line">{""}<span className="hljs-keyword">{"RUN"}</span>{" useradd "}<span className="hljs-attr">{"--create-home"}</span>{" appuser"}</div><div className="code-line">{""}<span className="hljs-keyword">{"WORKDIR"}</span>{" /app"}</div><div className="code-line">{""}<span className="hljs-keyword">{"COPY"}</span>{" "}<span className="hljs-attr">{"--chown=appuser:appuser"}</span>{" requirements.txt ."}</div><div className="code-line">{""}<span className="hljs-keyword">{"RUN"}</span>{" pip install "}<span className="hljs-attr">{"--no-cache-dir"}</span>{" -r requirements.txt"}</div><div className="code-line">{""}<span className="hljs-keyword">{"COPY"}</span>{" "}<span className="hljs-attr">{"--chown=appuser:appuser"}</span>{" . ."}</div><div className="code-line">{""}<span className="hljs-keyword">{"USER"}</span>{" appuser"}</div><div className="code-line">{""}<span className="hljs-keyword">{"CMD"}</span>{" ["}<span className="hljs-string">{"\"python\""}</span>{", "}<span className="hljs-string">{"\"main.py\""}</span>{"]"}</div></pre>
