    <div className={"table-scroll"} tabIndex={0} role="region" aria-label={"比較表 19：ロールの種類と使い分け"}>{"\n                    "}<table><thead><tr className={"header"}><th scope="col">{"名称"}</th><th scope="col">{"誰が引き受ける?"}</th><th scope="col">{"使う場面"}</th></tr></thead><tbody><tr className={"odd"}><td><strong>{"インスタンスプロファイル"}</strong></td><td>{"EC2 インスタンス"}</td><td>{"\n                                    EC2 上のアプリが S3、DynamoDB、SSM を呼ぶ。プロファイルは IAM\n                                    ロールを EC2 に渡す「入れ物」\n                                "}</td></tr><tr className={"even"}><td><strong>{"Lambda 実行ロール"}</strong></td><td>{"Lambda 関数"}</td><td>{"関数が CloudWatch Logs に書く、他サービスを呼ぶ"}</td></tr><tr className={"odd"}><td><strong>{"ECS タスクロール"}</strong></td><td>{"ECS タスク内のコンテナ"}</td><td>{"コンテナ内のアプリが AWS API を呼ぶ"}</td></tr><tr className={"even"}><td><strong>{"ECS タスク実行ロール"}</strong></td><td>{"ECS エージェント"}</td><td>{"イメージの ECR からの取得、ログ出力、シークレット取得"}</td></tr><tr className={"odd"}><td><strong>{"EKS: IRSA / EKS Pod Identity"}</strong></td><td>{"Kubernetes のサービスアカウント(Pod 単位)"}</td><td>{"Pod ごとに別の権限を与える"}</td></tr><tr className={"even"}><td><strong>{"サービスロール"}</strong></td><td>{"AWS サービス自体"}</td><td>{"\n                                    CloudFormation、CodePipeline\n                                    など、サービスが自分の代わりに操作を実行\n                                "}</td></tr><tr className={"odd"}><td><strong>{"サービスにリンクされたロール"}</strong></td><td>{"AWS サービス"}</td><td>{"\n                                    サービスが事前定義した権限で自分のために使う。ユーザーは編集不可\n                                "}</td></tr></tbody></table>{"\n                "}</div>
